import React, { useContext, useState } from "react";
import { SocketContext } from "../context/socket";
import { Form, Input, Button, Select } from 'antd';
import NavMenu from "./SharedComponents/navMenu";
import '../styles/myaccount.css';

const AddWorkspace = () => {
    const socket = useContext(SocketContext);
    const [form] = Form.useForm();

    const onFinish = async (values) => {
        const response = await fetch('/api/workspaces/add', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${localStorage.getItem('token')}`
            },
            body: JSON.stringify(values)
        });
        const data = await response.json();
        if (response.ok) {
            form.resetFields();
            alert('Workspace added successfully!');
        } else {
            alert(data.error);
        }
    };

    return (
        <div className="add-workspace">
            <NavMenu isAdmin={true} breadcrum="Add Workspace" pagePath="/add-workspace" />
            <Form form={form} onFinish={onFinish} layout="vertical">
                <Form.Item name="name" label="Workspace Name" rules={[{ required: true }]}>
                    <Input />
                </Form.Item>
                <Form.Item name="location" label="Location" rules={[{ required: true }]}>
                    <Input />
                </Form.Item>
                <Form.Item name="status" label="Status" initialValue="available">
                    <Select>
                        <Select.Option value="available">Available</Select.Option>
                        <Select.Option value="unavailable">Unavailable</Select.Option>
                    </Select>
                </Form.Item>
                <Button type="primary" htmlType="submit">
                    Add Workspace
                </Button>
            </Form>
        </div>
    );
};

export default AddWorkspace;





